function ref = mfun_ovhz_standby_output(enable, ref_in, fbk_in)
%MFUN_OVHZ_STANDBY_OUTPUT Block compute_standby_output of the control system.
%   Generated by motulator_export from the MATLAB port of motulator; the MATLAB Function
%   block of a model calls this function, copied into the folder of the model. The
%   parameters are the fields of the struct p, the struct of the block in the struct
%   ctrl_par of the parameters of the blocks of its control system (e.g.,
%   ctrl_par.SpeedController, see the function of the parameters of the control system,
%   e.g., fvc_params; [] as NaN).
fbk = im_observer_outputs_unpack(fbk_in);
% References of compute_output, or while the gates are blocked, of
% compute_standby_output
if enable > 0
    ref = ref_in;
else
    ref = [abs(fbk.psi_s); fbk.tau_M];
end
end

function s = im_observer_outputs_unpack(u)
%IM_OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'psi_R', complex(u(9), u(10)), ...
    'tau_M', u(11), ...
    'w_c', u(12), ...
    'w_s', u(13), ...
    'w_r', u(14), ...
    'w_m', u(15), ...
    'w_M', u(16), ...
    'theta_c', u(17), ...
    'e_o', complex(u(18), u(19)), ...
    'eps', u(20), ...
    'h', u(21));
end
